def faq_block(items=FAQS):
    return '<div class="faq-list">' + ''.join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in items) + '</div>'

def cta(title="Tell us what is happening"):
    return f'''<section class="cta"><div><p class="eyebrow">Clear information helps</p><h2>{title}</h2><p>Describe the current system, suburb, symptoms and what you need. Your enquiry can then be matched with a suitable local provider.</p></div><a class="button light" href="/contact/">Request a quote</a></section>'''

def layout(title, desc, body, path, schema_type="WebPage"):
    canonical = DOMAIN + (path if path.endswith('/') else path + '/')
    schema = json.dumps({"@context":"https://schema.org","@type":schema_type,"name":title,"description":desc,"url":canonical,"isPartOf":{"@type":"WebSite","name":"Orange Hot Water","url":f"{DOMAIN}/"}}, ensure_ascii=False)
    return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{schema}</script></head><body>{nav()}<main>{body}</main>{footer()}<script src="/assets/site.js" defer></script></body></html>'''

def write(path, html):
    target = OUT / path.strip('/') / "index.html" if path != "/" else OUT / "index.html"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html, encoding="utf-8")

